B.abh=s(["xylocaina con epinefrina","lidocaina con vasoconstrictor"],t.s)
B.a_y=new A.bo("Lidoca\xedna 2% con epinefrina","Anest\xe9sicos locales","infiltraci\xf3n y bloqueos: m\xe1x 7 mg/kg (\u2248500 mg = 25 ml al 2%)","fco 20 ml al 2% con epinefrina 1:100.000","teorico","la epinefrina alarga el bloqueo, baja el sangrado del campo y sube el m\xe1ximo de 4,5 a 7 mg/kg. Aspirar SIEMPRE: 15 ml intravascular dan taquicardia, HTA y arritmia. Evitar en coronariopat\xeda severa, hipertiroidismo y arritmias, y en dedos, pene y pabell\xf3n auricular",B.abh)
B.a_V=new A.bo("Ropivaca\xedna 0,75%","Anest\xe9sicos locales","peridural 75\u2013150 mg; bloqueos 0,2\u20130,5% seg\xfan volumen","fco 20 ml al 0,75% (7,5 mg/ml)","","menos cardiot\xf3xica que la bupivaca\xedna",B.t)
B.a_0=new A.bo("Efedrina","Vasoactivos","bolos 5\u201310 mg IV","amp 50 mg (diluir a 5 mg/ml)","","hipotensi\xf3n con bradicardia (raqu\xeddea)",B.t)
